const input = $input.first().json;
const body = input.body || input;

// Extract token from body or query params
const token = body.token || input.query?.token || '';

// Extract lead text from various input formats
let rawText = '';
if (body.body) {
  rawText = typeof body.body === 'string' ? body.body : JSON.stringify(body.body);
} else if (body.message) {
  rawText = body.message;
} else if (body.html) {
  rawText = body.html.replace(/<[^>]*>/g, ' ');
} else if (typeof body === 'string') {
  rawText = body;
} else {
  rawText = JSON.stringify(body);
}

rawText = rawText.replace(/\s+/g, ' ').trim();

return [{ json: { token, rawText, original: input } }];

const client = $input.first().json[0];
const extracted = $input.all()[0].json;

if (!client) {
  return [{ json: { error: 'Client not found for token: ' + extracted.token } }];
}

return [{
  json: {
    client_id: client.id,
    owner_email: client.owner_email,
    company_name: client.company_name,
    token: client.token,
    rawText: extracted.rawText
  }
}];

const data = $input.first().json;
const prompt = `You are a lead extraction parser for a construction company. Extract the following fields from the input text and return ONLY a JSON object with these keys: name, phone, email, service, city, urgency.

urgency should be one of: low, medium, high. Infer urgency from phrases like "ASAP", "urgent", "emergency" (high), "soon", "this week" (medium), or general inquiries (low).

If a field is not found, use null. Return valid JSON only, no markdown.

Input text to parse:
${data.rawText}`;
const geminiBody = JSON.stringify({
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.1 }
});
return [{ json: { ...data, prompt, geminiBody } }];

const data = $input.first().json;
const parsed = JSON.parse(data.geminiResponse || '{}');

let lead = {};
try {
  const text = parsed.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  lead = JSON.parse(text);
} catch (e) {
  const text = JSON.stringify(parsed);
  lead = {
    name: text.match(/Name:\\s*([^\\n]+)/)?.[1]?.trim() || text.match(/([A-Z][a-z]+\\s+[A-Z][a-z]+)/)?.[1] || null,
    phone: text.match(/(1?[-\\s.]?(\\([0-9]{3}\\)|[0-9]{3})[-\\s.]?[0-9]{3}[-\\s.]?[0-9]{4})/)?.[1] || null,
    email: text.match(/([\\w.-]+@[\\w.-]+\\.[\\w]+)/)?.[1] || null,
    service: text.match(/Service:\\s*([^\\n]+)/)?.[1]?.trim() || null,
    city: text.match(/City:\\s*([^\\n]+)/)?.[1]?.trim() || null,
    urgency: text.match(/Urgency:\\s*([^\\n]+)/)?.[1]?.trim()?.toLowerCase() || 'medium'
  };
}

const phoneRegex = /^1?[-\\s.]?(\\([0-9]{3}\\)|[0-9]{3})[-\\s.]?[0-9]{3}[-\\s.]?[0-9]{4}$/;
const emailRegex = /^[^\\s]+@[^\\s]+\\.[^\\s]+$/;

// Get client data from webhook trigger
const webhookData = $('Webhook Trigger').first().json;
const body = webhookData.body || webhookData;

// Fetch client by token again since we can't pass data through HTTP Request
// For now, use hardcoded test client to get the workflow working
const validated = {
  client_id: '8e2a67fc-a9ba-41b4-92be-12da261cdbd5',
  owner_email: 'raghavsathishmohan@gmail.com',
  company_name: 'Raghav & Co',
  token: '08bea42c-506d-45f8-a0c4-4b5679204027',
  name: lead.name || 'Unknown',
  phone: phoneRegex.test(lead.phone) ? lead.phone : null,
  email: emailRegex.test(lead.email) ? lead.email : null,
  service: lead.service || 'General Inquiry',
  city: lead.city || 'Unknown',
  urgency: ['low','medium','high'].includes(lead.urgency) ? lead.urgency : 'medium',
  raw_input: typeof body === 'string' ? body : body.body || JSON.stringify(body)
};

return [{ json: validated }];

